// refresh-ingredients.js
// Writes the app's copy of the owner's ingredient list (src/ingredients.json)
// from the workbook (data/Brew Design Ingredients.xlsx). SPEC rule 16: the
// copy is generated by this tool and never edited by hand.
//
//   npm run refresh-ingredients --workspace @brew/recipe
//   node apps/recipe/scripts/refresh-ingredients.js [workbook] [copy]
//
// Reads the saved file only (Excel's lock file, ~$…, is never read). A
// workbook the ingredient test would refuse writes nothing: the problems are
// printed, naming the sheet and row, and the tool exits with an error.
// Refreshing twice from the same workbook gives byte-identical text.

import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  WORKBOOK_PATH,
  COPY_PATH,
  readWorkbook,
  ingredientsFromWorkbook,
  formatCopy,
} from './ingredient-workbook.js';

export async function refreshIngredients(workbookPath = WORKBOOK_PATH, copyPath = COPY_PATH) {
  const { list, problems } = ingredientsFromWorkbook(await readWorkbook(workbookPath));
  if (problems.length) return { problems, list: null };
  writeFileSync(copyPath, formatCopy(list), 'utf8');
  return { problems, list };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [workbookPath = WORKBOOK_PATH, copyPath = COPY_PATH] = process.argv.slice(2).map((p) => resolve(p));
  const { problems, list } = await refreshIngredients(workbookPath, copyPath);
  if (problems.length) {
    console.error(`Refused ${workbookPath}; nothing written:`);
    for (const p of problems) console.error(`  ${p}`);
    process.exit(1);
  }
  console.log(
    `Wrote ${copyPath}: ${list.malts.length} malts, ${list.hops.length} hops, ${list.yeasts.length} yeasts.`,
  );
}
